import type { Locator, Page } from '@playwright/test'

type FilePayload = Readonly<{ name: string; mimeType: string; buffer: Buffer }>

function padded(contents: Buffer, sizeBytes: number): Buffer {
  return Buffer.concat([contents, Buffer.alloc(Math.max(0, sizeBytes - contents.length))])
}

function syntheticJpeg(width: number, height: number, sizeBytes = 12_000): Buffer {
  const header = Buffer.from([
    0xff, 0xd8,
    0xff, 0xc0, 0x00, 0x11, 0x08,
    (height >> 8) & 0xff, height & 0xff,
    (width >> 8) & 0xff, width & 0xff,
    0x03, 0x01, 0x11, 0x00, 0x02, 0x11, 0x00, 0x03, 0x11, 0x00,
    0xff, 0xd9,
  ])
  return padded(header, sizeBytes)
}

const VALID_SYNTHETIC_350_JPEG = Buffer.from(
  '',
  'base64',
)

const VALID_ONE_PIXEL_JPEG = Buffer.from(
  '',
  'base64',
)

export function validPhoto(name = 'synthetic-square-photo.jpg'): FilePayload {
  return { name, mimeType: 'image/jpeg', buffer: padded(VALID_SYNTHETIC_350_JPEG, 12_000) }
}

export function onePixelPhoto(): FilePayload {
  return { name: 'synthetic-one-pixel.jpg', mimeType: 'image/jpeg', buffer: padded(VALID_ONE_PIXEL_JPEG, 12_000) }
}

export function belowMinimumDimensionsPhoto(): FilePayload {
  return { name: 'synthetic-349-square.jpg', mimeType: 'image/jpeg', buffer: syntheticJpeg(349, 349) }
}

export function invalidNonSquarePhoto(): FilePayload {
  return { name: 'synthetic-non-square.jpg', mimeType: 'image/jpeg', buffer: syntheticJpeg(350, 349) }
}

export function undersizedPhoto(): FilePayload {
  return { name: 'synthetic-small.jpg', mimeType: 'image/jpeg', buffer: syntheticJpeg(350, 350, 9_000) }
}

export function oversizedPhoto(): FilePayload {
  return { name: 'synthetic-large.jpg', mimeType: 'image/jpeg', buffer: syntheticJpeg(350, 350, 1_048_577) }
}

export function wrongPdfType(): FilePayload {
  return { name: 'synthetic-support.txt', mimeType: 'text/plain', buffer: padded(Buffer.from('synthetic text'), 12_000) }
}

export function validPdf(name = 'synthetic-document.pdf', sizeBytes = 12_000): FilePayload {
  return { name, mimeType: 'application/pdf', buffer: padded(Buffer.from('%PDF-1.4\n% synthetic test artifact\n'), sizeBytes) }
}

export function invalidPng(): FilePayload {
  return { name: 'synthetic-photo.png', mimeType: 'image/png', buffer: padded(Buffer.from('synthetic png'), 12_000) }
}

export function undersizedPdf(): FilePayload {
  return validPdf('synthetic-small.pdf', 9_000)
}

export function oversizedPdf(): FilePayload {
  return validPdf('synthetic-large.pdf', 307_201)
}

export function documentCard(page: Page, name: string): Locator {
  return page.locator('article').filter({
    has: page.getByRole('heading', { level: 3, name }),
  })
}

export async function selectValidDocument(page: Page, name: string): Promise<void> {
  const card = documentCard(page, name)
  await card.getByLabel(/Choose file|Replace file/).setInputFiles(
    name === 'Recent photograph' ? validPhoto() : validPdf(`synthetic-${name.toLowerCase().replaceAll(' ', '-')}.pdf`),
  )
  await card.getByText('Ready', { exact: true }).waitFor()
}

export async function selectAllVisibleDocuments(page: Page): Promise<void> {
  await page.locator('main article input[type="file"]').first().waitFor()
  const cards = page.locator('main article')
  const count = await cards.count()
  for (let index = 0; index < count; index += 1) {
    const card = cards.nth(index)
    const name = await card.getByRole('heading', { level: 3 }).innerText()
    await selectValidDocument(page, name)
  }
}
